update dm_change_flow
set flow_manager_uid = #{newData},
    gmt_modified     = now()
where owner_uid = #{ownerUid}
  and id = #{flowId}

update dm_change_flow
set flow_name    = #{newData},
    gmt_modified = now()
where owner_uid = #{ownerUid}
  and id = #{flowId}

update dm_change_flow
set flow_desc    = #{newData},
    gmt_modified = now()
where owner_uid = #{ownerUid}
  and id = #{flowId}

update dm_change_flow
set flow_status  = #{newData,javaType=com.clougence.clouddm.platform.dal.model.cicd.ChangeFlowStatus},
    gmt_modified = now()
where owner_uid = #{ownerUid}
  and id = #{flowId}

